3	const mineflayer = require('mineflayer')
4	const { pathfinder, Movements } = require('mineflayer-pathfinder')
5	const { makeBrain } = require('./brain')
6	const { findTarget, buildState, stateKey } = require('./perception')
7	const { makeScout } = require('./behaviours/scout')
8	
9	const BEHAVIOURS = {
10	  follow: require('./behaviours/follow'),
11	}
12	
13	// Poll cadence when nobody is online: no JEV calls happen there, so waking
14	// up every 10 s just to re-scan the player list is plenty.
15	const IDLE_TICK_MS = 10000
16	const IDLE_LOG_MS = 60000
17	
18	function createTicker({ bot, brain, tickMs = 1000, idleTickMs = IDLE_TICK_MS, followName = '' }) {
19	  const ctx = { lastGoalKey: '', movements: null }
20	  let inFlight = false
21	  let lastTargetPos = null
22	  let lastVisible = true
23	  let lastIdleLog = 0
24	  let lastStateKey = null
25	  let lastDecision = null
26	
27	  function applyDecision(decision, target, state) {
28	    const handler = BEHAVIOURS[decision.action]
29	    if (typeof handler === 'function') {
30	      handler(bot, ctx, target, state)
31	    } else {
32	      if (ctx.lastGoalKey !== 'idle') bot.pathfinder.stop()
33	      ctx.lastGoalKey = 'idle'
34	    }
35	    if (ctx.movements) ctx.movements.allowSprinting = !!decision.sprint
36	    const dist = typeof state.distance_to_player === 'number' ? state.distance_to_player.toFixed(1) : 'none'
37	    console.log(`decision source=${decision.source} action=${decision.action} sprint=${decision.sprint} dist=${dist}`)
38	  }
39	
40	  function scheduleNext(fast) {
41	    const t = setTimeout(() => { void tick() }, fast ? tickMs : idleTickMs)
42	    if (t && typeof t.unref === 'function') t.unref()
43	  }
44	
45	  async function tick() {
46	    if (inFlight) { scheduleNext(lastVisible); return { decision: null, calledBrain: false } }
47	    inFlight = true
48	    let calledBrain = false
49	    try {
50	      const target = findTarget(bot, followName)
51	      lastVisible = !!target
52	      if (!target) {
53	        // Cost fix: nobody online => no brain call at all, decide idle
54	        // locally, stop once, and stay quiet (at most one line per minute).
55	        if (ctx.lastGoalKey !== 'idle') {
56	          bot.pathfinder.stop()
57	          ctx.lastGoalKey = 'idle'
58	        }
59	        lastTargetPos = null
60	        lastDecision = null
61	        lastStateKey = null
62	        const now = Date.now()
63	        if (now - lastIdleLog >= IDLE_LOG_MS) {
64	          lastIdleLog = now
65	          console.log('decision source=local-idle action=idle sprint=false dist=none')
66	        }
67	        return { decision: { action: 'idle', sprint: false, source: 'local-idle' }, calledBrain: false }
68	      }
69	      const state = buildState(bot, target, lastTargetPos)
70	      lastTargetPos = state._lastTargetPos
71	      // every-tick hooks (no body cost) go here
72	      if (!ctx.scout && bot.registry) ctx.scout = makeScout(bot)
73	      if (ctx.scout) ctx.scout.tick()
74	      const key = stateKey(state)
75	      let decision
76	      if (lastDecision && key === lastStateKey) {
77	        decision = lastDecision
78	      } else {
79	        decision = await brain.decide(state)
80	        calledBrain = true
81	        // A stub-fallback means JEV failed; don't cache it or JEV would
82	        // never be retried while the player stands still.
83	        if (decision.source !== 'stub-fallback') {
84	          lastStateKey = key
85	          lastDecision = decision
86	        }
87	      }
88	      applyDecision(decision, target, state)
89	      return { decision, calledBrain }
90	    } catch (err) {
91	      console.error(`tick error: ${err && err.message ? err.message : err}`)
92	      return { decision: null, calledBrain }
93	    } finally {
94	      inFlight = false
95	      scheduleNext(lastVisible)
96	    }
97	  }
98	
99	  return {
100	    tick,
101	    start: () => scheduleNext(true),
102	    setMovements: (m) => { ctx.movements = m; bot.pathfinder.setMovements(m) },
103	    setFollow: (name) => { followName = name; ctx.lastGoalKey = '' },
104	    stop: () => {
105	      if (ctx.lastGoalKey !== 'idle') bot.pathfinder.stop()
106	      ctx.lastGoalKey = 'idle'
107	    }
108	  }
109	}
110	
111	function main() {
112	  const rawTick = parseInt(process.env.BRAIN_TICK_MS || '1000', 10)
113	  const tickMs = Number.isFinite(rawTick) ? rawTick : 1000
114	  const brain = makeBrain(process.env)
115	  const bot = mineflayer.createBot({
116	    host: process.env.MC_HOST || 'mc',
117	    port: parseInt(process.env.MC_PORT || '25565', 10),
118	    username: process.env.BOT_USERNAME || 'IdkBot',
119	    auth: 'offline' // offline-mode server; see README for the online-mode note
